<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Rooms | Indus Resort</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/remixicon@3.5.0/fonts/remixicon.css" rel="stylesheet"><link rel="stylesheet" href="{{ asset('css/admin.css') }}"><link rel="stylesheet" href="{{ asset('css/admin-rooms.css') }}"><link rel="stylesheet" href="{{ asset('css/admin-room-actions.css') }}"><style>.current-images{margin:12px 0;padding:12px;border:1px solid #dfe9e4;border-radius:7px;background:#fbfdfc}.current-images h3{font-size:11px;margin:0 0 10px}.current-image-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:9px}.current-image{margin:0;border:1px solid #e5ebe8;border-radius:5px;overflow:hidden;background:#fff}.current-image img{display:block;width:100%;height:75px;object-fit:cover}.current-image figcaption{padding:5px 6px;font-size:8px;line-height:1.3;color:#647571;word-break:break-all;min-height:25px}.image-actions{display:flex;gap:4px;padding:5px}.image-actions form{margin:0}.image-actions button,.image-actions label{border:1px solid;border-radius:4px;padding:4px 5px;background:#fff;font:600 9px 'DM Sans';cursor:pointer;display:inline-flex;align-items:center;gap:3px}.image-actions label{color:#176044;border-color:#b9d7ca}.image-actions button{color:#b33038;border-color:#f0c7ca}.image-actions input{display:none}.edit-form-actions{display:flex;align-items:center;gap:9px;margin-top:16px}.edit-form-actions .save-room{margin:0}.cancel-edit{display:inline-flex;align-items:center;gap:5px;padding:9px 12px;border:1px solid #cad6d1;border-radius:5px;text-decoration:none;color:#51635d;font:600 11px 'DM Sans';background:#fff}.feature-picker,.kitchen-picker{border:0;padding:0;margin:0}.feature-picker legend,.kitchen-picker legend{font-size:11px;font-weight:700;color:#344843;margin-bottom:7px}.feature-picker legend small{display:block;font-size:9px;color:#70807d;font-weight:400;margin-top:2px}.feature-options{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.feature-options label,.kitchen-picker label{display:block!important}.feature-options input,.kitchen-picker input{position:absolute;opacity:0}.feature-options span,.kitchen-picker span{display:flex;align-items:center;gap:6px;border:1px solid #dfe4e1;border-radius:5px;padding:8px;font-size:10px;background:#fff;cursor:pointer}.feature-options input:checked+span,.kitchen-picker input:checked+span{background:#eaf6ef;border-color:#74b99b;color:#176044}.feature-options input:checked+span i{display:block}.feature-options span i{display:none}.kitchen-picker{display:flex;gap:8px;align-items:end}.kitchen-picker legend{width:100%}.kitchen-picker label{flex:1}@media(max-width:700px){.feature-options{grid-template-columns:1fr}.kitchen-picker{flex-wrap:wrap}.kitchen-picker legend{flex-basis:100%}}</style></head>
