<div class="room-admin-grid"><section class="panel room-form-panel"><h2><i class="{{ $editingRoom ? 'ri-pencil-line' : 'ri-add-circle-line' }}"></i> {{ $editingRoom ? 'Edit Room' : 'Add New Room' }}</h2><p class="form-caption">{{ $editingRoom ? 'Update details. Leave images empty to keep existing images.' : 'Upload 1 to 8 room images and fill in the details below.' }}</p><form method="POST" action="{{ route('admin.rooms.store') }}" enctype="multipart/form-data">@csrf @if($editingRoom)<input type="hidden" name="room_index" value="{{ $index }}">@endif<div class="room-fields"><label>Room Heading<input name="title" value="{{ old('title', $editingRoom['title'] ?? '') }}" required></label><label>Price Per Night<input name="price" value="{{ old('price', $editingRoom['price'] ?? '') }}" required></label><label>Rating (0–5)<input name="rating" type="number" min="0" max="5" step="0.1" value="{{ old('rating', $editingRoom['rating'] ?? '5.0') }}"></label><label>Bedrooms<input name="bedrooms" type="number" min="1" value="{{ old('bedrooms', $editingRoom['bedrooms'] ?? '1') }}" required></label><label>Persons<input name="persons" type="number" min="1" value="{{ old('persons', $editingRoom['persons'] ?? '2') }}" required></label><label class="wide">Description<textarea name="description" rows="4" required>{{ old('description', $editingRoom['description'] ?? '') }}</textarea></label><fieldset class="wide feature-picker"><legend>Room Features <small>Click to select amenities for the website</small></legend><div class="feature-options">@foreach(['TV Lounge','Dining Area','Balcony with Mountain View','Private Lawn Access','Huge Balcony'] as $feature)<label><input type="checkbox" name="feature_choices[]" value="{{ $feature }}" {{ in_array($feature, old('feature_choices', $editingRoom['features'] ?? [])) ? 'checked' : '' }}><span><i class="ri-check-line"></i>{{ $feature }}</span></label>@endforeach</div></fieldset><fieldset class="wide kitchen-picker"><legend>Kitchen Availability</legend><label><input type="radio" name="kitchen" value="yes" {{ old('kitchen', $editingRoom['kitchen'] ?? (in_array('Kitchen', $editingRoom['features'] ?? []) ? 'yes' : 'no')) === 'yes' ? 'checked' : '' }}><span><i class="ri-restaurant-line"></i> Kitchen Available</span></label><label><input type="radio" name="kitchen" value="no" {{ old('kitchen', $editingRoom['kitchen'] ?? (in_array('Kitchen', $editingRoom['features'] ?? []) ? 'yes' : 'no')) === 'no' ? 'checked' : '' }}><span><i class="ri-close-circle-line"></i> No Kitchen</span></label></fieldset><div class="wide custom-feature-add" style="display:grid;grid-template-columns:1fr auto;gap:8px"><label>Add Custom Feature <small>It will appear as a checked feature after you add it</small><input id="customFeatureInput" type="text" placeholder="e.g. Free Wi-Fi" onkeydown="if(event.key==='Enter'){event.preventDefault();addCustomFeature()}"></label><button type="button" class="save-room" style="margin:20px 0 0;padding:8px 11px;height:38px;align-self:end;font-size:11px" onclick="addCustomFeature()"><i class="ri-add-line"></i> Add Feature</button></div><label class="wide image-upload">Room Images <small>{{ $editingRoom ? 'Optional: add new images to the current set' : 'Select up to 8 JPG, JPEG, PNG or WEBP images' }}</small><input id="roomImages" name="images[]" type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" multiple {{ $editingRoom ? '' : 'required' }}><span><i class="ri-image-add-line"></i> {{ $editingRoom ? 'Add room images' : 'Choose room images' }}</span></label><div id="imageCount" class="image-count">{{ $editingRoom ? count($editingRoom['images']).' current images will be kept; new images will be added' : 'No images selected' }}</div><div id="selectedImagePreview" class="current-image-grid" style="margin-top:10px"></div><button id="saveSelectedImages" class="save-room" type="submit" style="display:none;margin-top:12px"><i class="ri-save-line"></i> Save Selected Images</button></div>@if($editingRoom)<div class="current-images"><h3><i class="ri-gallery-line"></i> Current images — manage individually</h3><div class="current-image-grid">@foreach($editingRoom['images'] as $imageIndex => $image)<figure class="current-image" id="image-card-{{ $imageIndex }}"><img src="{{ asset($image) }}" alt="Current room image"><figcaption class="image-name">{{ basename($image) }}</figcaption><div class="image-actions"><div class="replace-image-form"><input id="replace-{{ $imageIndex }}" name="image" type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" data-url="{{ route('admin.rooms.image.replace', [$index, $imageIndex]) }}" onchange="replaceImage(event,this,{{ $imageIndex }})"><label for="replace-{{ $imageIndex }}"><i class="ri-image-edit-line"></i> Replace</label></div><button type="button" data-url="{{ route('admin.rooms.image.delete', [$index, $imageIndex]) }}" onclick="deleteImage(event,this,{{ $imageIndex }})"><i class="ri-delete-bin-6-line"></i> Delete</button></div></figure>@endforeach</div></div>@endif
<div class="edit-form-actions"><button class="save-room" type="submit"><i class="{{ $editingRoom ? 'ri-save-line' : 'ri-add-line' }}"></i> {{ $editingRoom ? 'Save Room Changes' : 'Add Room & Publish' }}</button>@if($editingRoom)<a class="cancel-edit" href="{{ route('admin.rooms') }}"><i class="ri-close-line"></i> Cancel Edit</a>@endif</div></form></section><section class="panel existing-rooms"><div class="existing-heading"><div><h2><i class="ri-hotel-bed-line"></i> Published Rooms</h2><p>These rooms are currently live on your website.</p></div><span>{{ count($rooms) }} rooms</span></div><div class="published-list">@foreach($rooms as $roomIndex => $room)<article class="published-room"><img src="{{ asset($room['images'][0] ?? 'images/bed-image.jpg') }}" alt="{{ $room['title'] }}"><div class="published-details"><b>{{ $room['title'] }}</b><small>PKR {{ $room['price'] }} / Night · {{ count($room['images']) }} images</small><em>{{ $room['bedrooms'] }} Bedrooms · {{ $room['persons'] }} Persons</em></div><div class="room-actions"><a class="edit-room" href="{{ route('admin.rooms', ['edit' => $roomIndex]) }}"><i class="ri-pencil-line"></i><span>Edit</span></a><form method="POST" action="{{ route('admin.rooms.destroy', $roomIndex) }}" onsubmit="return confirm('Delete this room? This cannot be undone.');">@csrf @method('DELETE')<button class="delete-room" type="submit"><i class="ri-delete-bin-6-line"></i><span>Delete</span></button></form></div></article>@endforeach</div></section></div></main></div><script>const sidebar=document.getElementById('sidebar');document.querySelector('.menu-toggle').onclick=()=>sidebar.classList.add('open');document.querySelector('.sidebar-close').onclick=()=>sidebar.classList.remove('open');document.getElementById('roomImages').onchange=function(){const n=this.files.length;const box=document.getElementById('imageCount');const preview=document.getElementById('selectedImagePreview');const saveButton=document.getElementById('saveSelectedImages');preview.innerHTML='';if(n>8){this.value='';box.textContent='Please select a maximum of 8 images.';saveButton.style.display='none';return}saveButton.style.display=n?'inline-flex':'none';box.innerHTML=n?'<strong>'+n+' image'+(n>1?'s':'' )+' selected — ready to publish</strong><br><small style="line-height:1.8">'+Array.from(this.files).map(file=>file.name).join('<br>')+'</small>':'No images selected';Array.from(this.files).forEach(file=>{const card=document.createElement('figure');card.className='current-image';card.innerHTML='<img src="'+URL.createObjectURL(file)+'" alt="Selected image"><figcaption>New: '+file.name+'</figcaption>';preview.appendChild(card)})};function addCustomFeature(){const input=document.getElementById('customFeatureInput');const name=input.value.trim();if(!name)return;const options=document.querySelector('.feature-options');const exists=Array.from(options.querySelectorAll('input')).some(item=>item.value.toLowerCase()===name.toLowerCase());if(exists){notice('This feature is already added.',true);return}const label=document.createElement('label');const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.name='feature_choices[]';checkbox.value=name;checkbox.checked=true;const span=document.createElement('span');span.innerHTML='<i class="ri-check-line"></i>';span.appendChild(document.createTextNode(name));label.appendChild(checkbox);label.appendChild(span);options.appendChild(label);input.value='';notice('Feature added below. Click Save Room Changes to publish it.')} function notice(message,error=false){const n=document.getElementById('ajaxNotice');n.className='save-notice show';n.style.color=error?'#a42531':'#0b6e48';n.style.background=error?'#fff0f0':'#eaf6ef';n.innerHTML='<i class="ri-checkbox-circle-line"></i> '+message}async function replaceImage(e,input,index){e.preventDefault();if(!input.files.length)return;const body=new FormData();body.append('_token',document.querySelector('input[name=_token]').value);body.append('image',input.files[0]);try{const response=await fetch(input.dataset.url,{method:'POST',body,headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'Upload failed');const card=document.getElementById('image-card-'+index);card.querySelector('img').src=data.image+'?v='+Date.now();card.querySelector('.image-name').textContent=data.filename;notice('Image replaced successfully.')}catch(error){notice(error.message||'Image could not be replaced.',true)}input.value=''}async function deleteImage(e,button,index){if(!confirm('Delete this image?'))return;e.preventDefault();const body=new FormData();body.append('_token',document.querySelector('input[name=_token]').value);body.append('_method','DELETE');body.append('image_name',document.getElementById('image-card-'+index).querySelector('.image-name').textContent);try{const response=await fetch(button.dataset.url,{method:'POST',body,headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'Delete failed');const card=document.getElementById('image-card-'+index);if(data.fallback){card.querySelector('img').src='{{ asset('images/bed-image.jpg') }}';card.querySelector('.image-name').textContent='bed-image.jpg';notice('Last image removed; the default room image is now shown.')}else{card.remove();notice('Image deleted successfully.')}}catch(error){notice(error.message||'Image could not be deleted.',true)}}</script></body></html>
